// ── Shuttle widget ────────────────────────────────────────────────────────────

export function ShuttleWidget() {
  const startRef = useRef(Date.now() - INIT_ELAPSED_MS)
  const [elapsed, setElapsed] = useState(INIT_ELAPSED_MS)

  useEffect(() => {
    let raf: number
    const tick = () => {
      setElapsed(Date.now() - startRef.current)
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [])

  const cycleMs = elapsed % JOURNEY_MS
  const progress = cycleMs / JOURNEY_MS
  const etaSec = Math.ceil((JOURNEY_MS - cycleMs) / 1000)
  const etaMin = Math.ceil(etaSec / 60)

  const now = Date.now()
  const commArrival = new Date(now + etaSec * 1000)
  const hall7Arrival = new Date(now + (etaSec + 5 * 60) * 1000)

  return (
    <div style={{
      margin: '0 16px',
      background: 'rgba(24, 24, 26, 0.75)',
      backdropFilter: 'blur(28px)',
      WebkitBackdropFilter: 'blur(28px)',
      borderRadius: 22,
      padding: '14px 14px 14px 16px',
      display: 'flex',
      gap: 12,
      marginTop: 28
    }}>

      {/* ── Left panel ── */}
      <div style={{
        flex: 1, minWidth: 0,
        display: 'flex', flexDirection: 'column', justifyContent: 'space-between', gap: 10,
      }}>

        {/* Row 1: "Full Bus" pill + passenger avatars */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'nowrap' }}>
          <span style={{
            background: '#34A853', color: 'white',
            fontSize: 11, fontWeight: 700, letterSpacing: 0.2,
            padding: '3px 10px', borderRadius: 20, flexShrink: 0,
          }}>Full Bus</span>

          <div style={{ display: 'flex', alignItems: 'center' }}>
            {(['#5B9CF6', '#E8844F', '#B87DD4'] as const).map((bg, i) => (
              <div key={i} style={{
                width: 20, height: 20, borderRadius: '50%',
                background: bg,
                border: '1.5px solid rgba(0,0,0,0.55)',
                marginLeft: i === 0 ? 0 : -6,
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                flexShrink: 0,
              }}>
                {/* person silhouette */}
                <svg width="10" height="10" viewBox="0 0 24 24" fill="white">
                  <path d="M12 12c2.7 0 4.8-2.1 4.8-4.8S14.7 2.4 12 2.4 7.2 4.5 7.2 7.2 9.3 12 12 12zm0 2.4c-3.2 0-9.6 1.6-9.6 4.8v2.4h19.2v-2.4c0-3.2-6.4-4.8-9.6-4.8z" />
                </svg>
              </div>
            ))}
            <span style={{ fontSize: 11, color: 'rgba(255,255,255,0.55)', marginLeft: 6, fontWeight: 600 }}>60+</span>
          </div>
        </div>

        {/* Row 2: route progress bar */}
        <div>
          <div style={{ position: 'relative', height: 4, background: 'rgba(255,255,255,0.12)', borderRadius: 3, overflow: 'visible' }}>
            {/* filled track */}
            <div style={{
              position: 'absolute', left: 0, top: 0, bottom: 0,
              width: `${Math.min(progress * 100, 100)}%`,
              background: 'linear-gradient(90deg, #34A853, #4ECB6E)',
              borderRadius: 3,
            }} />
            {/* bus dot */}
            <div style={{
              position: 'absolute', top: '50%',
              left: `${Math.min(progress * 100, 100)}%`,
              transform: 'translate(-50%, -50%)',
              width: 12, height: 12, borderRadius: '50%',
              background: '#34A853',
              border: '2.5px solid white',
              boxShadow: '0 0 0 3px rgba(52,168,83,0.35)',
              zIndex: 1,
            }} />
          </div>
          {/* stop labels below the bar */}
          <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 5 }}>
            <span style={{ fontSize: 9, color: 'rgba(255,255,255,0.38)', fontWeight: 500 }}>Commercial Area</span>
            <span style={{ fontSize: 9, color: 'rgba(255,255,255,0.38)', fontWeight: 500 }}>Hall 7</span>
          </div>
        </div>

        {/* Row 3: ETA */}
        <div style={{ display: 'flex', alignItems: 'center', gap: 6 }}>
          {/* clock icon */}
          <svg width="13" height="13" viewBox="0 0 24 24" fill="rgba(255,255,255,0.55)">
            <path d="M11.99 2C6.47 2 2 6.48 2 12s4.47 10 9.99 10C17.52 22 22 17.52 22 12S17.52 2 11.99 2zM12 20c-4.42 0-8-3.58-8-8s3.58-8 8-8 8 3.58 8 8-3.58 8-8 8zm.5-13H11v6l5.25 3.15.75-1.23-4.5-2.67V7z" />
          </svg>
          <span style={{ fontSize: 11.5, color: 'rgba(255,255,255,0.82)', fontWeight: 500 }}>
            Bus will arrive in {etaMin} {etaMin === 1 ? 'min' : 'mins'}
          </span>
        </div>

        {/* Row 4: upcoming stops */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 6 }}>
          {/* stop 1 — active */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 7 }}>
            <div style={{ width: 6, height: 6, borderRadius: '50%', background: '#34A853', flexShrink: 0 }} />
            <span style={{ fontSize: 11, color: 'rgba(255,255,255,0.85)', flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              Commercial Area
            </span>
            <span style={{ fontSize: 11, color: 'rgba(255,255,255,0.55)', fontWeight: 600, flexShrink: 0 }}>
              {fmtTime(commArrival)}
            </span>
          </div>
          {/* stop 2 — upcoming */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 7 }}>
            <div style={{ width: 6, height: 6, borderRadius: '50%', background: 'rgba(255,255,255,0.22)', flexShrink: 0 }} />
            <span style={{ fontSize: 11, color: 'rgba(255,255,255,0.42)', flex: 1, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
              Hall 7
            </span>
            <span style={{ fontSize: 11, color: 'rgba(255,255,255,0.3)', fontWeight: 600, flexShrink: 0 }}>
              {fmtTime(hall7Arrival)}
            </span>
          </div>
        </div>
      </div>

      {/* ── Right panel: mini live map ── */}
      <div style={{
        width: 118, flexShrink: 0,
        borderRadius: 14, overflow: 'hidden',
        position: 'relative',
        minHeight: 140,
      }}>
        <ShuttleMap
          busRoutes={WIDGET_ROUTES}
          focusBusId="bus-3"
          focusZoom={15.8}
          focusDelayMs={0}
          routeCoords={ROUTE_B}
          routeColor="#34A853"
          skipRouteFitBounds
        />
        {/* subtle green border overlay */}
        <div style={{
          position: 'absolute', inset: 0,
          borderRadius: 14,
          border: '1.5px solid rgba(52,168,83,0.4)',
          pointerEvents: 'none',
        }} />
      </div>
    </div>
  )
}

